package com.mayamba.photocraftpreview;
import android.app.NativeActivity;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.provider.DocumentsContract;
import android.app.AlertDialog;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;
import org.json.JSONObject;

public final class PhotoCraftActivity extends NativeActivity {
 private static volatile java.lang.ref.WeakReference<PhotoCraftActivity> active=new java.lang.ref.WeakReference<>(null);
 public static PhotoCraftActivity current(){PhotoCraftActivity a=active.get();if(a==null||a.isDestroyed())throw new IllegalStateException("PhotoCraft activity is unavailable; return to the app and retry");return a;}
 @Override protected void onCreate(android.os.Bundle state){active=new java.lang.ref.WeakReference<>(this);super.onCreate(state);}
 private final ExecutorService files=Executors.newSingleThreadExecutor();
 private boolean saving; private String suggested;
 private String pickerResult="", platformError="";
 public synchronized String takePickerResult(){String s=pickerResult;pickerResult="";return s;}
 public synchronized String takePlatformError(){String s=platformError;platformError="";return s;}
 private synchronized void platformError(String text){platformError=text;}
 private File root(){File f=getExternalFilesDir(null);return f!=null?f:getFilesDir();}
 public void pickDocument(boolean save,String name){runOnUiThread(()->{synchronized(this){pickerResult="";}saving=save;suggested=name;
  boolean image=save&&mime(name).startsWith("image/");
  String[] choices=save?(image?new String[]{"Save to Gallery","Browse folders…","Android Files…"}:new String[]{"Browse folders…","Android Files…"}):new String[]{"Gallery / Photos","Browse folders…","Android Files / projects…"};
  new AlertDialog.Builder(this).setTitle(save?"Export / Save":"Import / Open").setItems(choices,(d,w)->{if((!save||image)&&w==0){if(save)saveGallery();else gallery();}else{int n=w-((!save||image)?1:0);if(n==0)browse();else systemPicker(null);}}).setNegativeButton("Cancel",(d,w)->result("cancel",null,null,null)).setOnCancelListener(d->result("cancel",null,null,null)).show();});}
 private void browse(){String stored=getPreferences(0).getString("folderUri","");if(stored.isEmpty())chooseFolder();else try{showFolder(Uri.parse(stored));}catch(Exception e){chooseFolder();}}
 private void gallery(){try{Intent i=new Intent("android.provider.action.PICK_IMAGES").setType("image/*");try{startActivityForResult(i,2101);}catch(ActivityNotFoundException e){i=new Intent(Intent.ACTION_GET_CONTENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(Intent.createChooser(i,"Choose image"),2101);}}catch(Exception e){result("error","Cannot open Gallery: "+e.getMessage(),null,null);}}
 private void saveGallery(){files.execute(()->{try{File dir=new File(root(),"exports");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Not enough storage");File target=new File(dir,safe(suggested));atomic(new File(target.getPath()+".uri"),"gallery".getBytes(StandardCharsets.UTF_8));result("save",null,target.getAbsolutePath(),target.getName());}catch(Exception e){result("error",e.getMessage(),null,null);}});}
 private void showFolder(Uri tree){new FolderBrowser(this,tree,saving,suggested,new FolderBrowser.Actions(){public void choose(Uri uri,String name){processUri(uri,saving,name);}public void folder(){chooseFolder();}public void system(Uri current){systemPicker(current);}public void cancel(){result("cancel",null,null,null);}}).show();}
 private void chooseFolder(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);String stored=getPreferences(0).getString("folderUri","");if(!stored.isEmpty())i.putExtra(DocumentsContract.EXTRA_INITIAL_URI,Uri.parse(stored));startActivityForResult(i,2102);}catch(Exception e){result("error","Cannot choose folder: "+e.getMessage(),null,null);}}
 private void systemPicker(Uri initial){try{Intent i=new Intent(saving?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(saving?mime(suggested):"*/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(saving)i.putExtra(Intent.EXTRA_TITLE,suggested);if(initial!=null)i.putExtra(DocumentsContract.EXTRA_INITIAL_URI,initial);startActivityForResult(i,2101);}catch(Exception e){result("error","Cannot open Android Files: "+e.getMessage(),null,null);}}
 @Override protected void onActivityResult(int request,int code,Intent data){super.onActivityResult(request,code,data);if(request!=2101&&request!=2102)return;if(code!=RESULT_OK||data==null||data.getData()==null){result("cancel",null,null,null);return;}final Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(SecurityException ignored){}
  if(request==2102){getPreferences(0).edit().putString("folderUri",uri.toString()).apply();try{showFolder(uri);}catch(Exception e){result("error","Cannot browse folder: "+e.getMessage(),null,null);}return;}processUri(uri,saving,suggested);
 }
 private void processUri(final Uri uri,final boolean save,final String fallback){
  files.execute(()->{try{String name=filename(uri,fallback);File dir=new File(root(),save?"exports":"imports");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Cannot create working folder; check free storage");File target=new File(dir,safe(name));if(!save){File unique=new File(dir,java.util.UUID.randomUUID().toString());if(!unique.mkdirs())throw new IOException("Cannot create import folder");target=new File(unique,safe(name));}
   if(save){atomic(new File(target.getPath()+".uri"),uri.toString().getBytes(StandardCharsets.UTF_8));result("save",null,target.getAbsolutePath(),name);}
   else{File temp=new File(target.getPath()+".part");try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException("The selected file could not be read");copy(in,out,128L<<20);out.getFD().sync();}catch(Exception e){temp.delete();throw e;}if(!temp.renameTo(target))throw new IOException("Cannot finish import; check free storage");atomic(new File(target.getPath()+".uri"),(mime(name).startsWith("image/")?"gallery":uri.toString()).getBytes(StandardCharsets.UTF_8));result("open",null,target.getAbsolutePath(),name);}
  }catch(Exception e){result("error","Cannot access selected file: "+e.getMessage(),null,null);}});
 }
 public String finishExport(String path){try{File f=new File(path),sidecar=new File(path+".uri");if(sidecar.exists()){ByteArrayOutputStream text=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(sidecar)){copy(in,text,65536);}String destination=new String(text.toByteArray(),StandardCharsets.UTF_8);if(destination.equals("gallery")){saveToGallery(f);return "";}Uri uri=Uri.parse(destination);try(InputStream in=new FileInputStream(f);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("The destination cannot be written");copy(in,out,512L<<20);}}
  if(f.getName().equals("PhotoCraft-share.png")){runOnUiThread(()->{try{Uri uri=Uri.parse("content://com.mayamba.photocraftpreview.exports/PhotoCraft-share.png");Intent share=new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);share.setClipData(ClipData.newRawUri("PhotoCraft image",uri));startActivity(Intent.createChooser(share,"Share image"));}catch(Exception e){platformError("Cannot share image: "+e.getMessage());android.util.Log.e("PhotoCraft","Cannot share image",e);}});}
  return "";
 }catch(Exception e){return "Cannot save to the selected destination: "+e.getMessage()+". Check free storage and file permissions. Your local backup was kept.";}}
 public void saveToGallery(File file)throws IOException{boolean video=file.getName().endsWith(".mp4");ContentValues values=new ContentValues();values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,file.getName());values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,video?"video/mp4":mime(file.getName()));values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,video?"Movies/PhotoCraft":"Pictures/PhotoCraft");values.put(android.provider.MediaStore.MediaColumns.IS_PENDING,1);Uri uri=getContentResolver().insert(video?android.provider.MediaStore.Video.Media.EXTERNAL_CONTENT_URI:android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Gallery destination unavailable");try{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("Gallery cannot be written");copy(in,out,512L<<20);}values.clear();values.put(android.provider.MediaStore.MediaColumns.IS_PENDING,0);getContentResolver().update(uri,values,null,null);}catch(Exception e){getContentResolver().delete(uri,null,null);throw new IOException("Gallery save failed; local backup retained: "+e.getMessage(),e);}}
 public void openExternal(String url){runOnUiThread(()->{try{Uri uri=Uri.parse(url);if(!"https".equals(uri.getScheme())&&!"http".equals(uri.getScheme()))throw new IllegalArgumentException("Unsupported link");startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){platformError("Cannot open link: "+e.getMessage());}});}
 public String exportTimelapse(String folder,int seconds){try{File output=new File(root(),"exports/PhotoCraft-timelapse-"+System.currentTimeMillis()+".mp4");if(!output.getParentFile().isDirectory()&&!output.getParentFile().mkdirs())throw new IOException("Cannot create export folder");TimelapseVideo.encode(new File(folder),output,seconds);saveToGallery(output);return "";}catch(Exception e){return "Timelapse export failed: "+e.getMessage();}}
 private String filename(Uri uri,String fallback){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()&&!c.isNull(0))return c.getString(0);}catch(Exception ignored){}return fallback==null?"Image":fallback;}
 private synchronized void result(String state,String error,String path,String name){try{JSONObject o=new JSONObject();o.put("state",state);if(error!=null)o.put("error",error);if(path!=null)o.put("path",path);if(name!=null)o.put("name",name);pickerResult=o.toString();}catch(Exception e){android.util.Log.e("PhotoCraft","File result failed",e);}}
 private static String safe(String name){String s=name.replaceAll("[\\\\/\\p{Cntrl}]","_");return s.isEmpty()||s.equals(".")||s.equals("..")?"Image":s;}
 private static void copy(InputStream in,OutputStream out,long limit)throws IOException{byte[] b=new byte[65536];long n=0;int read;while((read=in.read(b))!=-1){n+=read;if(n>limit)throw new IOException("File exceeds the Android safety limit");out.write(b,0,read);}out.flush();}
 private static void atomic(File target,byte[] bytes)throws IOException{File temp=new File(target.getPath()+".part");try(FileOutputStream out=new FileOutputStream(temp)){out.write(bytes);out.getFD().sync();}if(!temp.renameTo(target))throw new IOException("Cannot save file; check available storage");}
 static String mime(String name){String n=name.toLowerCase(java.util.Locale.ROOT);return n.endsWith(".png")?"image/png":n.endsWith(".jpg")||n.endsWith(".jpeg")?"image/jpeg":n.endsWith(".gif")?"image/gif":n.endsWith(".webp")?"image/webp":n.endsWith(".bmp")?"image/bmp":n.endsWith(".avif")?"image/avif":"application/octet-stream";}
}
